recipes.code:
{
  "inputs": [
    {
      "id": "frisk-api-key",
      "type": "promptString",
      "description": "Hosted API key. Without it the server screens entirely offline.",
      "password": true
    }
  ],
  "servers": {
    "frisk": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "frisk-mcp@0.0.1"
      ],
      "env": {
        "FRISK_API_KEY": "${input:frisk-api-key}",
        "FRISK_BASE_URL": "<frisk-base-url>"
      }
    }
  }
}
